CREATE TABLE coaches (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,title TEXT NOT NULL,bio TEXT NOT NULL,hourly_rate INTEGER NOT NULL,rating REAL NOT NULL DEFAULT 5,specialty TEXT NOT NULL,tags TEXT NOT NULL,color TEXT NOT NULL,initial TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE bookings (id INTEGER PRIMARY KEY AUTOINCREMENT,coach_id INTEGER NOT NULL REFERENCES coaches(id),player_name TEXT NOT NULL,player_email TEXT NOT NULL,session_date TEXT NOT NULL,session_time TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(coach_id,session_date,session_time));
